//! `cli/internal/completions/bash` witnesses for
//! `packages/effect/test/cli/completions/completions.test.ts` (Bash section).
//!
//! The oracle is the pin itself: each fixture's script was generated by the
//! upstream `bash.ts` and committed under `fixtures/completions/bash/`, so the
//! byte-equality test below is stricter than the pin's `assert.include` rows.
//! Each `#[test]` names the upstream line it proves.

use elm_effect_unstable::cli::primitive::PathKind;
use elm_effect_unstable::cli_completions::bash;
use elm_effect_unstable::cli_completions::{
    ArgumentDescriptor, ArgumentType, CommandDescriptor, DescriptorCommand, FlagDescriptor,
    FlagType, ParamDef, ParamType, from_command,
};

// ---------------------------------------------------------------------------
// Fixtures, mirroring the pin's `completions.test.ts` command builders.
// ---------------------------------------------------------------------------

fn tricky_values() -> Vec<String> {
    [
        "it's-fine",
        "node:20",
        "with space",
        "(whoami)",
        "#tag",
        "$HOME",
        "back\\slash",
        "say\"hi\"",
        "a*b",
        "a;b",
        "~x",
        "foo'",
        "a!b",
        "\u{1F680}",
    ]
    .iter()
    .map(|s| (*s).to_owned())
    .collect()
}

fn flag(name: &str, aliases: &[&str], flag_type: FlagType) -> FlagDescriptor {
    FlagDescriptor {
        name: name.to_owned(),
        aliases: aliases.iter().map(|a| (*a).to_owned()).collect(),
        description: None,
        flag_type,
    }
}

fn argument(name: &str, argument_type: ArgumentType) -> ArgumentDescriptor {
    ArgumentDescriptor {
        name: name.to_owned(),
        description: None,
        required: true,
        variadic: false,
        argument_type,
    }
}

fn tool() -> CommandDescriptor {
    CommandDescriptor {
        name: "tool".to_owned(),
        description: None,
        flags: vec![
            flag("verbose", &["v"], FlagType::Boolean),
            flag(
                "format",
                &["f"],
                FlagType::Choice(vec!["json".to_owned(), "text".to_owned()]),
            ),
        ],
        arguments: vec![
            argument("source", ArgumentType::Choice(vec!["one".to_owned()])),
            argument("target", ArgumentType::Choice(vec!["two".to_owned()])),
        ],
        subcommands: vec![],
    }
}

fn simple() -> CommandDescriptor {
    from_command(
        &DescriptorCommand::new("greet")
            .with_description("Greet someone")
            .with_flags(vec![
                ParamDef::flag("loud", ParamType::Boolean)
                    .with_alias("l")
                    .with_description("Shout the greeting"),
                ParamDef::flag("times", ParamType::Int).with_description("Repeat count"),
            ])
            .with_arguments(vec![
                ParamDef::argument("name", ParamType::String).with_description("Name to greet"),
            ]),
        &[],
    )
}

fn server() -> CommandDescriptor {
    let start = DescriptorCommand::new("start")
        .with_description("Start the server")
        .with_flags(vec![
            ParamDef::flag("port", ParamType::Int)
                .with_alias("p")
                .with_description("Port number"),
            ParamDef::flag("daemon", ParamType::Boolean).with_description("Run as daemon"),
        ]);
    let stop = DescriptorCommand::new("stop")
        .with_description("Stop the server")
        .with_flags(vec![
            ParamDef::flag("force", ParamType::Boolean)
                .with_alias("f")
                .with_description("Force stop"),
        ]);
    from_command(
        &DescriptorCommand::new("server")
            .with_description("Server management")
            .with_flags(vec![
                ParamDef::flag("verbose", ParamType::Boolean).with_alias("v"),
                ParamDef::flag("config", ParamType::String),
            ])
            .with_subcommands(vec![start, stop]),
        &[],
    )
}

fn choices() -> CommandDescriptor {
    from_command(
        &DescriptorCommand::new("deploy")
            .with_description("Deploy application")
            .with_flags(vec![
                ParamDef::flag(
                    "env",
                    ParamType::Choice(vec![
                        "dev".to_owned(),
                        "staging".to_owned(),
                        "prod".to_owned(),
                    ]),
                )
                .with_description("Target environment"),
            ])
            .with_arguments(vec![
                ParamDef::argument(
                    "region",
                    ParamType::Choice(vec![
                        "us-east".to_owned(),
                        "eu-west".to_owned(),
                        "ap-south".to_owned(),
                    ]),
                )
                .with_description("Deployment region"),
            ]),
        &[],
    )
}

fn tricky() -> CommandDescriptor {
    from_command(
        &DescriptorCommand::new("deploy")
            .with_description("Deploy application")
            .with_flags(vec![
                ParamDef::flag("mode", ParamType::Choice(tricky_values()))
                    .with_description("Deploy mode"),
            ])
            .with_arguments(vec![
                ParamDef::argument(
                    "target",
                    ParamType::Choice(
                        ["o'clock", "a:b", "{x,y}", "a\u{1F600}b"]
                            .iter()
                            .map(|s| (*s).to_owned())
                            .collect(),
                    ),
                )
                .with_description("Deployment target"),
            ]),
        &[],
    )
}

fn paths() -> CommandDescriptor {
    from_command(
        &DescriptorCommand::new("process")
            .with_description("Process files")
            .with_flags(vec![
                ParamDef::flag("input", ParamType::Path(PathKind::File))
                    .with_description("Input file"),
                ParamDef::flag("output-dir", ParamType::Path(PathKind::Directory))
                    .with_description("Output directory"),
            ])
            .with_arguments(vec![
                ParamDef::argument("source", ParamType::Path(PathKind::File))
                    .with_description("Source file"),
            ]),
        &[],
    )
}

fn optionaldir() -> CommandDescriptor {
    from_command(
        &DescriptorCommand::new("example").with_arguments(vec![
            ParamDef::argument("directory", ParamType::Path(PathKind::Directory))
                .with_description("Directory to start in")
                .optional(),
        ]).with_subcommands(vec![
            DescriptorCommand::new("serve").with_description("Start the server"),
        ]),
        &[],
    )
}

fn nested() -> CommandDescriptor {
    let leaf = DescriptorCommand::new("action")
        .with_description("Perform action")
        .with_flags(vec![
            ParamDef::flag("dry-run", ParamType::Boolean).with_description("Dry run mode"),
        ]);
    let mid = DescriptorCommand::new("sub").with_subcommands(vec![leaf]);
    from_command(
        &DescriptorCommand::new("top").with_subcommands(vec![mid]),
        &[],
    )
}

fn noop() -> CommandDescriptor {
    from_command(
        &DescriptorCommand::new("noop").with_description("Does nothing"),
        &[],
    )
}

/// Every fixture with the executable name the pin used and its committed
/// golden script (generated by the pin's own `bash.ts`).
fn goldens() -> Vec<(&'static str, &'static str, CommandDescriptor, &'static str)> {
    vec![
        (
            "tool",
            "tool",
            tool(),
            include_str!("fixtures/completions/bash/tool.bash"),
        ),
        (
            "simple",
            "greet",
            simple(),
            include_str!("fixtures/completions/bash/simple.bash"),
        ),
        (
            "server",
            "server",
            server(),
            include_str!("fixtures/completions/bash/server.bash"),
        ),
        (
            "choices",
            "deploy",
            choices(),
            include_str!("fixtures/completions/bash/choices.bash"),
        ),
        (
            "tricky",
            "deploy",
            tricky(),
            include_str!("fixtures/completions/bash/tricky.bash"),
        ),
        (
            "paths",
            "process",
            paths(),
            include_str!("fixtures/completions/bash/paths.bash"),
        ),
        (
            "optionaldir",
            "example",
            optionaldir(),
            include_str!("fixtures/completions/bash/optionaldir.bash"),
        ),
        (
            "nested",
            "top",
            nested(),
            include_str!("fixtures/completions/bash/nested.bash"),
        ),
        (
            "noop",
            "noop",
            noop(),
            include_str!("fixtures/completions/bash/noop.bash"),
        ),
    ]
}

/// The pin's own generator output, byte for byte. This subsumes the
/// `assert.include` rows below; the per-row tests stay for ledger traceability.
#[test]
fn bash_script_matches_pin_goldens_byte_for_byte() {
    for (fixture, executable, descriptor, golden) in goldens() {
        assert_eq!(
            bash::generate(executable, &descriptor),
            golden,
            "bash script for fixture `{fixture}` diverged from the pin"
        );
    }
}

// ---------------------------------------------------------------------------
// Rows from `completions.test.ts`, Bash section.
// ---------------------------------------------------------------------------

#[test]
fn completes_the_active_positional_argument_instead_of_always_using_the_first() {
    // :141
    let script = bash::generate("tool", &tool());
    assert!(script.contains("for ((i = _command_index + 1; i < cword; i++)); do"));
    assert!(script.contains("--verbose|-v|--no-verbose) ;;"));
    assert!(script.contains("--format|-f) _skip_next=1 ;;"));
    assert!(script.contains("--format=*|-f=*) ;;"));
    assert!(script.contains("0)\n      _tool--choices \"$cur\" \"$_comp_word\" 'one'"));
    assert!(script.contains("1)\n      _tool--choices \"$cur\" \"$_comp_word\" 'two'"));
}

#[test]
fn generates_completion_function_for_root_command() {
    // :187
    let script = bash::generate("greet", &simple());
    assert!(script.contains("_greet()"));
    assert!(script.contains("complete -F _greet greet"));
    assert!(script.contains("_init_completion -n \"$COMP_WORDBREAKS\" || return"));
}

