#[test]
fn quotes_choice_values_instead_of_exposing_them_to_compgen_re_expansion() {
    // :256
    let script = bash::generate("deploy", &tricky());
    let choice_lines: Vec<&str> = script
        .lines()
        .filter(|line| line.contains("_deploy--choices \"$cur\""))
        .map(|line| line.trim())
        .collect();
    assert_eq!(
        choice_lines.join("\n"),
        "_deploy--choices \"$cur\" \"$_comp_word\" 'it'\\''s-fine' 'node:20' 'with space' '(whoami)' '#tag' '$HOME' 'back\\slash' 'say\"hi\"' 'a*b' 'a;b' '~x' 'foo'\\''' 'a!b' '\u{1F680}'\n_deploy--choices \"$cur\" \"$_comp_word\" 'o'\\''clock' 'a:b' '{x,y}' 'a\u{1F600}b'"
    );
    assert!(!script.contains("compgen -W 'it"));
}

#[test]
fn splits_words_on_whitespace_only_so_a_value_holding_a_word_break_character_stays_one_word() {
    // :265
    let script = bash::generate("deploy", &tricky());
    assert!(script.contains("_init_completion -n \"$COMP_WORDBREAKS\" || return"));
}

#[test]
fn emits_the_choice_helper() {
    // :270
    let script = bash::generate("deploy", &tricky());
    let start = script.find("_deploy--choices()").expect("helper missing");
    let end = script[start..].find("\n}\n").expect("helper end missing");
    assert_eq!(&script[start..start + end + 2], CHOICE_HELPER_EXPECTED);
}

const CHOICE_HELPER_EXPECTED: &str = r##"_deploy--choices()
{
  local _cur="$1" _word="$2"; shift 2

  local _head="${_cur%"$_word"}"
  local _open=""
  case "$_head" in
    *\') _open="'" ;;
    *\") _open='"' ;;
  esac

  local _prefix="$_cur" _committed="$_head"
  _prefix=${_prefix//\\/}; _prefix=${_prefix//\"/}; _prefix=${_prefix//\'/}
  _committed=${_committed//\\/}; _committed=${_committed//\"/}; _committed=${_committed//\'/}

  COMPREPLY=()
  local _choice _rest _match
  for _choice in "$@"; do
    [[ "$_choice" == "$_prefix"* ]] || continue
    _rest="${_choice#"$_committed"}"
    case "$_open" in
      "'")
        if [[ "$_head" == "'" ]]; then
          _match=${_rest//\'/\'\\\'\'}
        else
          [[ "$_rest" == *\'* ]] && continue
          _match="$_rest"
        fi
        ;;
      '"')
        _match="${_rest//\\/\\\\}"
        _match="${_match//\$/\\$}"
        _match="${_match//\`/\\\`}"
        _match="${_match//\"/\\\"}"
        ;;
      *)
        printf -v _match '%q' "$_rest"
        [[ -z "$_head" && "$_match" == '~'* ]] && _match="\\$_match"
        ;;
    esac
    [[ -n "$_open" && "$_match" == *"$_open" ]] && _match+="$_open"
    COMPREPLY+=("$_match")
  done
}"##;

#[test]
fn generates_separate_functions_for_nested_subcommands() {
    // :320
    let script = bash::generate("server", &server());
    assert!(script.contains("_server()"));
    assert!(script.contains("_server_start()"));
    assert!(script.contains("_server_stop()"));
    assert!(script.contains("_server_start \"$i\""));
}

#[test]
fn handles_commands_with_no_subcommands() {
    // :329
    let script = bash::generate("noop", &noop());
    assert!(script.contains("_noop()"));
    assert!(script.contains("complete -F _noop noop"));
}

#[test]
fn generates_deeply_nested_functions() {
    // :336
    let script = bash::generate("top", &nested());
    assert!(script.contains("_top()"));
    assert!(script.contains("_top_sub()"));
    assert!(script.contains("_top_sub_action()"));
}

#[test]
fn wraps_script_in_begin_end_markers() {
    // :344
    let script = bash::generate("greet", &simple());
    assert!(script.contains("###-begin-greet-completions-###"));
    assert!(script.contains("###-end-greet-completions-###"));
}

#[test]
fn groups_flag_aliases_for_used_flag_filtering() {
    // :351
    let script = bash::generate("greet", &simple());
    assert!(script.contains("--loud|-l|--no-loud) _used_0=1 ;;"));
    assert!(script.contains("--times) _used_1=1 ;;"));
    assert!(script.contains("[[ -n \"$_used_0\" ]] || _filtered_flags+=\" --loud -l --no-loud\""));
    assert!(script.contains("[[ -n \"$_used_1\" ]] || _filtered_flags+=\" --times\""));
    assert!(script.contains("compgen -W \"$_filtered_flags\""));
}

#[test]
fn does_not_generate_flag_groups_for_commands_with_no_flags() {
    // :362
    let script = bash::generate("noop", &noop());
    assert!(!script.contains("_used_0"));
    assert!(!script.contains("_filtered_flags"));
}

#[test]
fn uses_no_bash_4_syntax_so_the_script_runs_on_the_bash_macos_ships() {
    // :369
    // The pin proves this on ComprehensiveCli; the generator has no array
    // literals at all, so the invariant holds across every generated script.
    for (fixture, executable, descriptor, _golden) in goldens() {
        let script = bash::generate(executable, &descriptor);
        assert!(!script.contains("local -A"), "{fixture}: local -A");
        assert!(!script.contains("declare -A"), "{fixture}: declare -A");
    }
}

#[test]
fn includes_inline_init_completion_fallback() {
    // :375
    let script = bash::generate("greet", &simple());
    assert!(script.contains("if ! type _init_completion &>/dev/null; then"));
    assert!(script.contains("COMPREPLY=()"));
    assert!(script.contains("if [[ \"$_line\" == [[:blank:]]* ]]; then"));
    assert!(script.contains("((_i == COMP_CWORD)) && cword=$_j"));
    assert!(script.contains("cur=\"${words[cword]}\""));
}
